mapper.select:
SELECT aio.id, aio.event_id, aio.change_kind, aio.status, aio.retry_count, aio.max_retry, aio.next_retry_at, aio.last_error, aio.locked_by, aio.locked_at, aio.processed_at, aio.source_module, aio.source_biz_id, aio.created_at, aio.updated_at, aio.created_by, aio.updated_by FROM sys_authorization_invalidation_outbox aio
AND aio.event_id LIKE CONCAT( #{query.eventId}, '%' )
AND aio.change_kind = #{query.changeKind}
AND aio.status = #{query.status}
AND aio.source_module = #{query.sourceModule}
AND aio.source_biz_id LIKE CONCAT( #{query.sourceBizId}, '%' )
AND aio.created_at >= #{query.createdAtStart}
AND aio.created_at <= #{query.createdAtEnd}
AND aio.processed_at >= #{query.processedAtStart}
AND aio.processed_at <= #{query.processedAtEnd}
ORDER BY aio.created_at DESC
